 for(const t of cr){c.rel[t]=(c.rel[t]||0)-30;G.c[t].rel[c.tag]=(G.c[t].rel[c.tag]||0)-30;}G.bankr=(G.bankr||0)+1;(G.defaults=G.defaults||[]).push({t:G.t,tag:c.tag,amt:old});if(G.defaults.length>60)G.defaults.shift();
