const BUILD_COST={timber:3000,cement:500,machinery:150},RAIL_COST={timber:2400,cement:300,steel:250},BUILD_RATE=.1;
const costOf=b=>b.k==="upg"?b.cost:b.k==="rail"?RAIL_COST:b.k==="bld"?(b.cost||BLD[b.b].cost):BUILD_COST;
