const thTypeOf=u=>u.k==="cav"?"cav":UNITS[u.k].sup2===1?"art":"inf";
function thGet(tag,reg,make){G.th=G.th||{};const T=G.th[tag]=G.th[tag]||{};let t=T[reg];if(!t&&make)t=T[reg]={st:"hold",ob:"",it:1,pr:1,t0:G.t};return t;}
