"use strict";
/* ================= HISTORY: events that fire when the world allows them ================= */
WARGOALS.annex={n:"Annex the state",inf:6,ws:60};
const alive=t=>G.c[t]&&G.c[t].alive,owns=(t,id)=>P(id).o===t;
function spawnNation(tag,n,adj,col,cul,gov,ideo,provs,from){const f=G.c[from];G.c[tag]=Object.assign(mkNation({tag,n,adj,col,cap:provs[0],gov,ideo,cul,acc:[],lit:f.lit,civ:f.civ,pres:10,tech:[0,0,0,0,0]}),{alive:true});const c=G.c[tag];c.tech=Object.assign({},f.tech);c.reforms=Object.assign({},f.reforms);
 for(const t in G.c){G.c[t].rel[tag]=0;c.rel[t]=0;}for(const id of provs)transferProv(P(id),tag);c.ai=tag!==G.player;c.tr=(f.stat.inc||1000)*3;c.stat={N:{},pop:popOf(tag)};return c;}
function annexAll(winner,loser){for(const p of provsOf(loser))transferProv(p,winner);}
/* ---- A3: who is asked. The observer seat (G.player) never changes a material outcome. When history reaches the nation a human is playing (the control flag: G.player and not ai) the human is asked on a decision card with a yes/no and the AI takes "yes"; the card's "yes" has exactly the consequences the AI default has. Headless and AI-run seats never wait. ---- */
const humanSeat=t=>!!t&&t===G.player&&!!G.c[t]&&!G.c[t].ai;
function askHuman(tag,ctx,title,txt,yes,no){if(!humanSeat(tag))return false;return cardOpen({kind:"dec",ctx,title,txt,def:"yes",opts:[{k:"yes",label:yes[0],txt:yes[1]},{k:"no",label:no[0],txt:no[1]}]});}
/* a nation the dice have called into a war: the AI joins, the human chooses */
function pullIn(w,t,side){if(askHuman(t,{a:"join",w:w.id,t,side},"Called into a war",nameOf(w.att[0])+" and "+nameOf(w.def[0])+" are at war, and "+nameOf(side===1?w.att[0]:w.def[0])+" calls on us.",["Join the war","We enter the war on "+nameOf(side===1?w.att[0]:w.def[0])+"'s side, as an allied nation would."],["Stay out","We stay neutral. No war, no gains."]))return;joinWar(w,t,side);}
function toSphere(t,lord){if(!alive(t))return;if(askHuman(t,{a:"sphere",t,lord},"A great neighbour offers its leadership",nameOf(lord)+" claims leadership over us.",["Accept","We enter "+nameOf(lord)+"'s sphere."],["Refuse","We stay as we are."]))return;G.c[t].sphere=lord;G.c[t].overlord=null;}
function toAnnex(lord,t,why){if(!alive(t))return;if(askHuman(t,{a:"annex",lord,t},why||"Union with "+nameOf(lord),nameOf(lord)+" asks us to join it outright.",["Join "+nameOf(lord),"Our lands and people join "+nameOf(lord)+" and our state ends."],["Remain independent","We keep our state. Nothing changes."]))return;annexAll(lord,t);}
function decRun(ctx,k){if(k!=="yes")return;const a=ctx.a;
 if(a==="join"){const w=G.wars.find(x=>x.id===ctx.w);if(w&&alive(ctx.t))joinWar(w,ctx.t,ctx.side);}
 else if(a==="sphere"){if(alive(ctx.t)){G.c[ctx.t].sphere=ctx.lord;G.c[ctx.t].overlord=null;}}
 else if(a==="annex"){if(alive(ctx.t)&&alive(ctx.lord))annexAll(ctx.lord,ctx.t);}
 else if(a==="plebiscite")plebisciteDo(ctx.to,ctx.id);
 else if(a==="annexSphere")annexSphereDo(ctx.lord,ctx.t);
 else if(a==="westernise")modWestDo(ctx.t);
 else if(a==="companyLahore")companyLahoreDo();}
function plebisciteDo(to,id){const p=P(id);if(!p.o||p.o===to||!alive(to))return false;transferProv(p,to);msg("politics","A plebiscite joins "+p.n+" to "+G.c[to].n+".");return true;}
function plebiscite(to,id){const p=P(id),o=p.o;if(!o||o===to)return false;if(askHuman(o,{a:"plebiscite",to,id},"A plebiscite in "+p.n,"The people of "+p.n+" are asked whether they wish to join "+nameOf(to)+".",["Hold the vote","The province joins "+nameOf(to)+"."],["Refuse the vote","We keep the province."]))return true;return plebisciteDo(to,id);}
function annexSphereDo(lord,t){const c=G.c[lord],m=G.c[t];if(!c||!m||!c.alive||!m.alive)return;annexAll(lord,t);c.infamy+=5;msg("diplomacy",m.n+" is annexed by "+c.n+".");}
const EVENTS=[
 {id:"famine",y:1845,run(){if(!owns("GBR","IRE"))return;G.famine={p:"IRE",until:G.t+60};msg("politics","Potato blight: famine grips Ireland. Hundreds of thousands will die or leave.");}},
 {id:"y1848",y:1848,run(){for(const t in G.c){const c=G.c[t];if(!c.alive||!c.civ||c.gov!=="abs")continue;const eu=P(c.cap).x>1250&&P(c.cap).x<1700&&P(c.cap).y<520;if(!eu)continue;for(const p of provsOf(t))for(const q of p.pops)if(PTYPES[q.t].s>0||q.t==="CRA")q.mil=Math.min(10,q.mil+2.5);}msg("politics","1848: revolution sweeps Europe's capitals.");}},
 {id:"taiping",y:1850,run(){if(!alive("CHI")||!owns("CHI","NAN"))return;const a=mkArmy("REB","NAN",{inf:30,cav:6});a.reb={key:"I:REA",vs:"CHI"};G.armies.push(a);const b=mkArmy("REB","WUH",{inf:16,cav:3});b.reb={key:"I:REA",vs:"CHI"};G.armies.push(b);msg("war","The Taiping Heavenly Kingdom rises in the south of China.");}},
 {id:"italy1",y:1859,cond:()=>alive("SAR")&&alive("AUS")&&owns("AUS","LOM")&&!G.c.SAR.war.length&&G.c.SAR.civ&&(G.c.SAR.truce.AUS||0)<=G.t&&(G.c.AUS.truce.SAR||0)<=G.t,run(){const w=declareWar("SAR","AUS",{k:"conquer",tag:"AUS",prov:"LOM",hist:1});if(w){w.unify="ITA";stayOut(w,["RUS","PRU"]);}if(w&&alive("FRA")&&!G.c.FRA.ally.includes("AUS"))pullIn(w,"FRA",1);}},
 /* A2: the 1859 war is a one-shot that SAR+FRA lose in about one run in four (A2 measurement: 4 of 16 runs, spread evenly over the rule variants), and a lost war blocked unification for the rest of the century. Like the German war's late fallback (R8), the same war is renewed in 1866 if it was lost and the two powers are free, truce over and for every seat (A3): a human SAR or AUS gets the same renewal as a card (renew, or wait two years; AUS may fight or cede Lombardy), the AI renews. */
 {id:"italy3",y:1866,cond:()=>alive("SAR")&&alive("AUS")&&G.ev.italy1!=null&&!(G.unif&&G.unif.ITA)&&!formedAlive("ITA")&&!G.c.SAR.formed&&owns("AUS","LOM")&&!G.c.SAR.war.length&&G.c.SAR.civ&&(G.c.SAR.truce.AUS||0)<=G.t&&(G.c.AUS.truce.SAR||0)<=G.t,run(){ev("italy1").run();}},
 {id:"italy2",y:1860,repeat:1,cond:()=>alive("SAR")&&(owns("SAR","LOM")||yearOf(G.t)>=1866),run(){let n=0;for(const id of["TUS","ROM","NAP","PAL"])if(rng()<.35&&P(id).c==="italian"&&!isGP(P(id).o||""))n+=plebiscite("SAR",id)?1:0;return["TUS","ROM","NAP","PAL","LOM"].every(id=>owns("SAR",id)||yearOf(G.t)>1875);}},
 {id:"germany1",y:1864,cond:()=>alive("PRU")&&alive("DEN")&&owns("DEN","SLH")&&!G.c.PRU.war.length,run(){const w=declareWar("PRU","DEN",{k:"conquer",tag:"DEN",prov:"SLH",hist:1});if(w&&alive("AUS")&&G.c.AUS.ally.includes("PRU"))pullIn(w,"AUS",1);}},
 {id:"germany2",y:1866,cond:()=>alive("PRU")&&alive("AUS")&&!G.c.PRU.war.length&&!G.c.AUS.war.length&&(G.c.PRU.truce.AUS||0)<=G.t&&(G.c.AUS.truce.PRU||0)<=G.t&&(landPow("PRU")>=.8*landPow("AUS")||yearOf(G.t)>=1869),run(){G.c.PRU.ally=G.c.PRU.ally.filter(t=>t!=="AUS");G.c.AUS.ally=G.c.AUS.ally.filter(t=>t!=="PRU");const w=declareWar("PRU","AUS",{k:"humble",tag:"AUS",hist:1});if(!w)return;for(const t of["HAN","SAX","BAV","WUR"])if(alive(t)&&rng()<.5)pullIn(w,t,2);if(alive("SAR")&&!G.c.SAR.war.length)pullIn(w,"SAR",1);w.german=1;w.unify="GER";w.ws=15;stayOut(w,["RUS","FRA","GBR"]);}},
 /* A2: the same gap for the German war: it is a one-shot and PRU lost it in 2 of the 4 seeds here (7 and 21; war score -32 and -28), after which unification was closed for good. Renewed once after the truce, under the same conditions as germany2 with a later fallback year (R8); a human PRU or AUS gets it as a card (A3), the AI renews. */
 {id:"germany4",y:1868,cond:()=>alive("PRU")&&alive("AUS")&&G.ev.germany2!=null&&!(G.unif&&G.unif.GER)&&!formedAlive("GER")&&!G.c.PRU.formed&&!G.c.PRU.war.length&&!G.c.AUS.war.length&&(G.c.PRU.truce.AUS||0)<=G.t&&(G.c.AUS.truce.PRU||0)<=G.t&&(landPow("PRU")>=.8*landPow("AUS")||yearOf(G.t)>=1872),run(){ev("germany2").run();}},
 {id:"germany3",y:1870,cond:()=>alive("PRU")&&alive("FRA")&&owns("FRA","LOR")&&!G.c.PRU.war.length&&!G.c.FRA.war.length&&G.ev.germany2,run(){const w=declareWar("PRU","FRA",{k:"conquer",tag:"FRA",prov:"LOR",hist:1});if(w)for(const t of["BAV","WUR","SAX"])if(alive(t)&&G.c[t].sphere==="PRU")pullIn(w,t,1);}},
  {id:"civilwar",y:1861,cond:()=>alive("USA")&&G.c.USA.reforms.slavery<2&&owns("USA","RIC")&&owns("USA","NOL"),run(){const south=["RIC","NOL"].concat(owns("USA","TEX")?["TEX"]:[]);const c=spawnNation("CSA","Confederate States","Confederate","#8b8b6b","american","dem","CON",south,"USA");
  /* the South takes the share of the Union's standing army that its people are of the nation; the rest stays loyal and the Union calls up its reserves. A2: conscript brigades (u.mob) belong to the Union's mobilisation plan and are not split: on seed 3 the secession came in the middle of the 1860 great-power war and the South walked off with a third of ~45 conscripts, an army that no mobilisation of its own would ever release, while the Union demobilised the rest (Confederate troops 26-32 against the usual 10; the Union lost). */
  {const U=G.c.USA,sh=popOf("CSA")/Math.max(1,popOf("CSA")+popOf("USA")),pool=[];for(const a of G.armies)if(a.o==="USA"&&!a.naval&&!a.reb)for(const u of a.u)if(!u.mob)pool.push([a,u]);const take=new Set();let n=Math.round(pool.length*sh);while(n>0&&take.size<pool.length){const i=Math.floor(rng()*pool.length);if(!take.has(i)){take.add(i);n--;}}
   const give=pool.filter((x,i)=>take.has(i)).map(x=>x[1]);for(const a of G.armies)if(a.o==="USA")a.u=a.u.filter(u=>!give.includes(u));G.armies=G.armies.filter(a=>a.u.length||a.o!=="USA"||a.naval);
   const half=Math.ceil(give.length/2),A1=mkArmy("CSA","RIC",{}),A2=mkArmy("CSA",provsOf("CSA").some(p=>p.id==="NOL")?"NOL":"RIC",{});A1.u=give.slice(0,half);A2.u=give.slice(half);for(const a of [A1,A2])if(a.u.length)G.armies.push(a);
   const w=declareWar("USA","CSA",{k:"annex",tag:"CSA",hist:1});if(w)w.civil=1;if(U.ai&&typeof mobilize==="function")mobilize(U);}msg("war","The Southern states secede: civil war in America.");}}];
function eventsMonth(){const y=yearOf(G.t);G.ev=G.ev||{};for(const e of EVENTS){if(G.ev[e.id]!=null&&!e.repeat)continue;if(y<e.y||(e.repeat&&G.ev[e.id]===true))continue;if(e.date!=null&&G.t<e.date)continue;
  if(e.until!=null&&G.t>e.until)continue;
  if(e.cond&&!e.cond())continue;if(e.repeat&&G.t%12!==0)continue;if(G.evWait&&G.evWait[e.id]>G.t)continue;
  if(e.ch&&G.player&&!G.c[G.player].ai&&e.ch.who().includes(G.player)){if(G.card)continue;const k=e.ch.build(G.player);if(k&&cardOpen({kind:"ev",id:e.id,title:k.title,txt:k.txt,history:k.history,opts:k.opts.map(o=>({k:o.k,label:o.label,txt:o.txt})),def:k.def||k.opts[0].k})){G.ev[e.id]=G.t;continue;}}
  const done=e.run();G.ev[e.id]=e.repeat?(done?true:G.t):G.t;}
 if(G.famine){const p=P(G.famine.p);if(G.t>G.famine.until)G.famine=null;else for(const q of p.pops)if(q.t==="FAR"||q.t==="LAB"){q.ld=Math.min(q.ld,.35+.1*bxl(p,"silo"));if(G.t%3===0){const out=q.n*.006;q.n-=out;const d=P("NYC");if(d.o==="USA"){let x=d.pops.find(z=>z.t==="CRA"&&z.c===q.c)||d.pops.find(z=>z.t==="FAR"&&z.c===q.c);if(!x){x=mkPop("FAR",q.c,0,q.lit,Object.assign({},q.id));d.pops.push(x);}x.n+=out*.6;}}}}
 for(const t of["SAR","PRU"]){const c=G.c[t];if(!c||!c.alive||c.formed||formedAlive(t==="SAR"?"ITA":"GER")||!unifyOpen(t==="SAR"?"ITA":"GER",c))continue;const u=UNIFY[t==="SAR"?"ITA":"GER"],have=u.need.filter(id=>{const o=P(id).o;return o===t||(o&&G.c[o].sphere===t);}).length;if(have>=u.min-(t==="PRU"&&G.ev.germany3?1:0)){c.formed=null;formNation(c,t==="SAR"?"ITA":"GER");}}}
function formNation(c,tag){if(formedAlive(tag))return;const d=DORMANT.find(x=>x[0]===tag),u=UNIFY[tag];{const asked=new Set();for(const id of u.need){const o=P(id).o;if(o&&o!==c.tag&&G.c[o].sphere===c.tag&&!asked.has(o)){asked.add(o);toAnnex(c.tag,o,"The "+(tag==="ITA"?"Kingdom of Italy":"German Empire")+" is proclaimed");}}}
 c.n=d[1];c.adj=d[2];c.col=d[3];c.formed=tag;if(c.cul!==d[5]&&!c.acc.includes(d[5]))c.acc.push(d[5]);c.pres+=25;const txt=tag==="ITA"?"Unification! The Kingdom of Italy is proclaimed.":"Unification! The German Empire is proclaimed.";msg("politics",txt);G.log.unshift({t:G.t,txt});}
/* great powers outside the quarrel stay neutral (data-driven: events name who stays out) */
function landPow(t){return sum(G.armies.filter(a=>a.o===t&&!a.reb&&!a.naval),strength);}
function stayOut(w,tags){if(!w)return;for(const t of tags){const c=G.c[t];if(!c||t===w.att[0]||t===w.def[0])continue;if(!w.att.includes(t)&&!w.def.includes(t))continue;w.att=w.att.filter(x=>x!==t);w.def=w.def.filter(x=>x!==t);c.war=c.war.filter(x=>x!==w.id);}}
/* a war won wholesale */
{const _ew=endWar;endWar=function(w,winner){const A=G.c[w.att[0]],D=G.c[w.def[0]];if(A&&D){A.lastWar=A.lastWar||{};D.lastWar=D.lastWar||{};A.lastWar[D.tag]={t:G.t,res:winner==="att"?"won":winner==="def"?"lost":"draw"};D.lastWar[A.tag]={t:G.t,res:winner==="def"?"won":winner==="att"?"lost":"draw"};}
 if(winner==="att"&&A&&D&&w.goal.k==="annex"){if(!w.civil&&!w.goal.hist){A.infamy+=conqInf(A,D,1,D.civ?2.2:1);for(const p of provsOf(D.tag))noteGain(A,p.id,D.tag);}annexAll(A.tag,D.tag);if(w.civil){A.reforms.slavery=2;msg("politics","The Union is restored. Slavery is abolished.");}}
 if(w.unify&&winner==="att"&&A){G.unif=G.unif||{};G.unif[w.unify]=A.tag;}
 if(w.german&&winner==="att"&&A){if(alive("HAN"))toAnnex(A.tag,"HAN","The German war is won");for(const t of["SAX","BAV","WUR"])if(alive(t))toSphere(t,A.tag);}
 return _ew.apply(this,arguments);};}
{const _po=peaceOffer;peaceOffer=function(w,kind){if(kind!=="max")return _po.apply(this,arguments);const side=w.att.includes(G.player)?1:2,ws=side===1?w.ws:-w.ws,them=side===1?w.def:w.att,need=side===1?WARGOALS[w.goal.k].ws:0;
 if(ws<need+15)return{ok:false,txt:"Our war score ("+Math.round(ws)+") does not stretch that far."};let budget=ws-need;const take=G.plist.filter(p=>p.ctl===G.player&&them.includes(p.o)).sort((a,b)=>b.pop-a.pop);const got=[];
 for(const p of take){const cost=15+p.pop/Math.max(1,popOf(p.o))*60;if(cost>budget)continue;budget-=cost;got.push(p);}
 if(side===1)endWar(w,"att");else endWar(w,"white");for(const p of got)takeProv(p,G.player,w);return{ok:true,txt:"Peace signed"+(got.length?": we also take "+got.map(p=>p.n).join(", ")+".":".")};};}

/* ================= DECISION CARDS ================= */
/* When history reaches the player's nation, the game stops on a card with two or three plain choices. The card is saved with the game. Nobody else (and no headless run) ever waits: the AI takes the old automatic course. */
function cardOpen(c){if(!G.player||!G.c[G.player]||G.c[G.player].ai||G.card)return false;G.card=Object.assign({t:G.t},c);msg("politics","A decision awaits: "+c.title+".");return true;}
function cardChoose(k){const c=G.card;if(!c)return null;const o=c.opts.find(x=>x.k===k);if(!o)return null;G.card=null;G.choices=G.choices||[];G.choices.push({t:G.t,id:c.id||c.kind,title:c.title,k:o.k,label:o.label,history:c.history});
 if(c.kind==="cong")crisisResolve(c.ctx,o.k);else if(c.kind==="july")chooseJulyCard(c,o.k);else if(c.kind==="dec")decRun(c.ctx,o.k);else{const e=EVENTS.find(x=>x.id===c.id),b=e&&e.ch&&e.ch.build(G.player),op=b&&b.opts.find(x=>x.k===o.k);if(op)op.run();}
 return o;}
function cardDefault(){if(G.card)cardChoose((G.card.opts.find(o=>o.k===G.card.def)||G.card.opts[0]).k);}
const incOf=c=>c.stat&&c.stat.inc||1000,evAt=(id,n)=>{G.ev=G.ev||{};G.evWait=G.evWait||{};delete G.ev[id];G.evWait[id]=G.t+n;};
const ev=id=>EVENTS.find(e=>e.id===id),pay=(c,x)=>{c.tr-=x;};
function evWar(a,d,goal,joinD,joinA){const w=declareWar(a,d,goal);if(!w)return null;for(const t of joinD||[])if(alive(t)&&!w.att.includes(t)&&rng()<.8)pullIn(w,t,2);for(const t of joinA||[])if(alive(t)&&!w.def.includes(t)&&rng()<.8)pullIn(w,t,1);return w;}
function crimea(){return evWar("RUS","OTT",{k:"humble",tag:"OTT",hist:1},["GBR","FRA"]);}
function rebelsIn(id,vs,inf,cav){const a=mkArmy("REB",id,{inf,cav});a.reb={key:"I:REA",vs};G.armies.push(a);}
function mutiny(sz){if(sz>0){rebelsIn("DEL","GBR",sz,Math.ceil(sz/5));rebelsIn("CAL","GBR",Math.ceil(sz*.55),1);}}
const freeAfrica=()=>G.plist.filter(p=>!p.o&&!p.waste&&!p.colz&&p.f.includes("U")&&AFRICA.has(p.id));
/* the conference gives every power the right to stake a claim on land nobody holds, whatever its colonial tools */
function claimAfrica(c,n){let k=0;const L=freeAfrica().sort((a,b)=>b.pop-a.pop);for(const p of L){if(k>=n)break;p.colz={tag:c.tag,left:12};k++;}return k;}
EVENTS.push(
 {id:"crimea",y:1853,cond:()=>alive("RUS")&&alive("OTT")&&!G.c.RUS.war.length&&!G.c.OTT.war.length&&G.c.OTT.sphere!=="RUS"&&G.c.RUS.rel.OTT<20,run(){if(rng()<.6)crimea();else msg("diplomacy","Russia presses the Sultan over the Holy Places and the Straits, but a settlement is found.");},
  ch:{who:()=>["RUS","OTT","GBR","FRA"],build:pt=>{const base="Russia demands a protectorate over the Sultan's Christian subjects and a say over the Straits.";
   if(pt==="RUS")return{title:"The Eastern Question, 1853",txt:base+" Britain and France may side with the Sultan.",def:"war",opts:[{k:"war",label:"Send the army across the Danube",txt:"War with the Ottomans, who will probably have British and French help. Prestige to be won, and lost.",run(){crimea();}},{k:"talk",label:"Settle by treaty",txt:"No war. Relations with the Ottomans improve; we lose 2 prestige for backing away.",run(){G.c.RUS.pres=Math.max(0,G.c.RUS.pres-2);G.c.RUS.rel.OTT=(G.c.RUS.rel.OTT||0)+25;G.c.OTT.rel.RUS=(G.c.OTT.rel.RUS||0)+25;}}]};
   if(pt==="OTT")return{title:"The Eastern Question, 1853",txt:base+" Britain and France say they will stand by us if we refuse.",def:"war",opts:[{k:"war",label:"Refuse and fight",txt:"War with Russia. British and French help is likely (about 8 in 10 each).",run(){crimea();}},{k:"yield",label:"Accept the Russian terms",txt:"No war. We lose 8 prestige and pay Russia a share of our income for three years.",run(){const c=G.c.OTT;c.pres=Math.max(0,c.pres-8);G.c.RUS.pres+=5;c.owes=(c.owes||[]).concat([{to:"RUS",share:.15,until:G.t+36}]);}}]};
   return{title:"Russia moves on the Ottomans, 1853",txt:base+" Russia may go to war to get it.",def:"stay",opts:[{k:"join",label:"Stand with the Sultan",txt:"If war comes we fight beside the Ottomans against Russia.",run(){const w=evWar("RUS","OTT",{k:"humble",tag:"OTT",hist:1},["GBR","FRA"].filter(t=>t!==G.player));if(w&&!w.def.includes(G.player))joinWar(w,G.player,2);}},{k:"stay",label:"Stay out of it",txt:"The war starts without us. Our relations with Russia stay as they are.",run(){evWar("RUS","OTT",{k:"humble",tag:"OTT",hist:1},["GBR","FRA"].filter(t=>t!==G.player));}}]};}}},
 {id:"mutiny",y:1857,cond:()=>alive("GBR")&&owns("GBR","DEL")&&owns("GBR","CAL"),run(){mutiny(18);msg("war","The Indian Mutiny: the Company's sepoys rise in Hindustan and Bengal.");},
  ch:{who:()=>["GBR"],build:()=>({title:"The Indian Mutiny, 1857",txt:"The sepoys have risen across the north of India. Garrisons are cut off and a quarrel over greased cartridges has become a rebellion.",def:"crush",opts:[{k:"crush",label:"Crush it with force",txt:"A large revolt breaks out in Hindustan and Bengal. Our armies must retake the towns.",run(){mutiny(18);msg("war","The Indian Mutiny: the sepoys rise in Hindustan and Bengal.");}},{k:"reform",label:"Pardon and reform",txt:"A smaller revolt. We pay three months of income and lose 2 prestige, but India settles sooner.",run(){const c=G.c.GBR;pay(c,incOf(c)*3);c.pres=Math.max(0,c.pres-2);mutiny(8);msg("war","The Indian Mutiny: a smaller rising in Hindustan; pardons are offered.");}},{k:"troops",label:"Rush troops from home",txt:"Ten extra regiments arrive at once (two months of income), but the revolt is still large.",run(){const c=G.c.GBR;pay(c,incOf(c)*2);mutiny(15);G.armies.push(mkArmy("GBR","DEL",{inf:10}));msg("war","The Indian Mutiny: reinforcements sail for Calcutta.");}}]})}},
 {id:"meiji",y:1868,cond:()=>alive("JAP")&&!G.c.JAP.civ&&!(G.c.JAP.hold>G.t)&&G.ev.meijiChoice==null,run(){if(takeDecision(G.c.JAP,"meiji").ok)msg("politics","The Meiji Restoration begins in Japan.");},
  ch:{who:()=>["JAP"],build:()=>({title:"The Meiji Restoration, 1868",txt:"The shogun has fallen and the young Emperor's circle holds power. They look at the steamships of the West.",def:"west",opts:[{k:"west",label:"Copy the West at once",txt:"Japan is counted among the civilized nations now, with a constitutional government. Mills come slowly at first.",run(){takeDecision(G.c.JAP,"meiji");}},{k:"old",label:"Keep the old order",txt:"No reform for ten years. We gain 4 prestige at home, but the West will call us backward and our mills wait.",run(){const c=G.c.JAP;if(c.civ||c.hold>G.t)return;c.hold=G.t+120;c.pres+=4;msg("politics","Japan restores the old order and puts off reform.");}}]})}},
 {id:"berlin",y:1884,cond:()=>(G.gp||[]).length>0&&freeAfrica().length>=2,run(){let n=0;for(const t of G.gp||[]){const c=G.c[t];if(c&&c.alive&&c.ai&&claimAfrica(c,1))n++;}msg("diplomacy","The Berlin Conference: the powers carve up Africa among themselves.");},
  ch:{who:()=>G.gp||[],build:pt=>({title:"The Berlin Conference, 1884",txt:"The powers meet to divide the last free land in Africa. Each wants a share without a war over it.",def:"fair",opts:[{k:"big",label:"Claim all we can",txt:"Two colonies start at once. Every other Great Power thinks less of us (relations down by 8).",run(){const c=G.c[pt];claimAfrica(c,2);for(const x of G.gp)if(x!==pt){G.c[x].rel[pt]=(G.c[x].rel[pt]||0)-8;c.rel[x]=(c.rel[x]||0)-8;}for(const t of G.gp||[]){const o=G.c[t];if(t!==pt&&o.ai)claimAfrica(o,1);}}},{k:"fair",label:"Back a fair division",txt:"One colony starts at once, relations with the other powers improve by 6, and we gain 3 prestige.",run(){const c=G.c[pt];claimAfrica(c,1);c.pres+=3;for(const x of G.gp)if(x!==pt){G.c[x].rel[pt]=(G.c[x].rel[pt]||0)+6;c.rel[x]=(c.rel[x]||0)+6;}for(const t of G.gp||[]){const o=G.c[t];if(t!==pt&&o.ai)claimAfrica(o,1);}}},{k:"out",label:"Stay out of Africa",txt:"No colonies, no quarrels. We save two months of income and lose 1 prestige.",run(){const c=G.c[pt];c.tr+=incOf(c)*2;c.pres=Math.max(0,c.pres-1);for(const t of G.gp||[]){const o=G.c[t];if(t!==pt&&o.ai)claimAfrica(o,1);}}}]})}},
 {id:"rjwar",y:1904,cond:()=>alive("RUS")&&alive("JAP")&&!G.c.RUS.war.length&&!G.c.JAP.war.length&&G.c.JAP.civ,run(){if(rng()<.4&&(G.c.JAP.score?G.c.JAP.score.mil:0)>(G.c.RUS.score?G.c.RUS.score.mil:0)*.4)declareWar("JAP","RUS",{k:"humble",tag:"RUS"});else{G.c.JAP.rel.RUS=(G.c.JAP.rel.RUS||0)-15;G.c.RUS.rel.JAP=(G.c.RUS.rel.JAP||0)-15;msg("diplomacy","Russia and Japan quarrel over Manchuria and Korea.");}},
  ch:{who:()=>["RUS","JAP"],build:pt=>{const t=pt==="RUS"?"Japan":"Russia";const R=()=>{const a=G.c.JAP,b=G.c.RUS;a.rel.RUS=(a.rel.RUS||0)+25;b.rel.JAP=(b.rel.JAP||0)+25;};
   if(pt==="JAP")return{title:"Manchuria and Korea, 1904",txt:"Russia's railway and fleet at Port Arthur threaten our hold on Korea. The army and navy want to strike before Russia grows stronger.",def:"talk",opts:[{k:"strike",label:"Strike first at Port Arthur",txt:"War with Russia, which is much larger. Great Powers may call a congress first. A win would raise our standing for good.",run(){declareWar("JAP","RUS",{k:"humble",tag:"RUS"});}},{k:"talk",label:"Offer a treaty on spheres",txt:"Russia holds Manchuria, we hold Korea. Relations improve by 25; no war.",run:R}]};
   return{title:"Manchuria and Korea, 1904",txt:"Japan wants us out of Korea and says it will fight for it. Our railway runs deep into Manchuria.",def:"hold",opts:[{k:"hold",label:"Hold firm",txt:"Relations with Japan fall by 30 and Japan may declare war. We gain 2 prestige at home.",run(){const c=G.c.RUS;c.pres+=2;G.c.JAP.rel.RUS=(G.c.JAP.rel.RUS||0)-30;c.rel.JAP=(c.rel.JAP||0)-30;if(G.c.JAP.ai&&rng()<.6)declareWar("JAP","RUS",{k:"humble",tag:"RUS"});}},{k:"talk",label:"Divide spheres by treaty",txt:"We leave Korea to Japan. Relations improve by 25; we lose 2 prestige.",run(){G.c.RUS.pres=Math.max(0,G.c.RUS.pres-2);R();}}]};}}},
 {id:"balkan",y:1912,cond:()=>alive("AUS")&&alive("RUS")&&alive("OTT")&&!G.c.AUS.war.length&&!G.c.RUS.war.length&&isGP("AUS")&&isGP("RUS"),run(){for(const[a,b]of[["AUS","RUS"],["RUS","AUS"]])G.c[a].rel[b]=(G.c[a].rel[b]||0)-30;if(rng()<.25)declareWar("AUS","RUS",{k:"humble",tag:"RUS"});else msg("diplomacy","The Balkan states defeat the Ottomans; Austria and Russia glare at each other across the new borders.");},
  ch:{who:()=>["AUS","RUS"],build:pt=>{const o=pt==="AUS"?"RUS":"AUS",on=G.c[o].n,me=pt,conf={k:"conf",label:"Call a conference of the powers",txt:"Both sides back off. Relations with "+on+" improve by 15; we lose 3 prestige.",run(){const c=G.c[me];c.pres=Math.max(0,c.pres-3);c.rel[o]=(c.rel[o]||0)+15;G.c[o].rel[me]=(G.c[o].rel[me]||0)+15;}};
   return{title:"The Balkan crisis, 1912",txt:"The Balkan states have beaten the Ottomans and fallen out over the spoils. "+(pt==="AUS"?"Serbia, backed by Russia, wants an Adriatic port that we cannot accept.":"Serbia is our client, and Austria threatens to crush it.")+" Both our armies are on alert.",def:"conf",opts:[{k:"firm",label:pt==="AUS"?"Mobilize and send an ultimatum":"Back the Slavs",txt:"Relations with "+on+" fall by 40. War is declared on "+on+"; the other powers may call a congress first. We gain 3 prestige.",run(){const c=G.c[me];c.pres+=3;c.rel[o]=(c.rel[o]||0)-40;G.c[o].rel[me]=(G.c[o].rel[me]||0)-40;declareWar(me,o,{k:"humble",tag:o});}},conf]};}}},
 {id:"boxers",y:1900,cond:()=>alive("CHI")&&owns("CHI","PEK"),run(){rebelsIn("PEK","CHI",8,1);msg("war","The Boxers rise in northern China against foreigners and Christians.");},
  ch:{who:()=>["CHI"],build:()=>({title:"The Boxers, 1900",txt:"A secret society blames foreigners for the nation's ills and its bands are marching on Peking. The court is split.",def:"crush",opts:[{k:"crush",label:"Put them down",txt:"A small revolt near Peking. It costs one month of income and the court loses 1 prestige.",run(){const c=G.c.CHI;pay(c,incOf(c));c.pres=Math.max(0,c.pres-1);rebelsIn("PEK","CHI",5,1);}},{k:"back",label:"Back the Boxers",txt:"No revolt and 5 prestige at home, but every Great Power's relations with us fall by 30.",run(){const c=G.c.CHI;c.pres+=5;for(const x of G.gp||[]){G.c[x].rel.CHI=(G.c[x].rel.CHI||0)-30;c.rel[x]=(c.rel[x]||0)-30;}}},{k:"help",label:"Ask the powers for troops",txt:"The powers restore order. Relations with them improve by 10 but we lose 5 prestige.",run(){const c=G.c.CHI;c.pres=Math.max(0,c.pres-5);for(const x of G.gp||[]){G.c[x].rel.CHI=(G.c[x].rel.CHI||0)+10;c.rel[x]=(c.rel[x]||0)+10;}}}]})}});
/* the old scripted events, now with a choice when the player is the nation concerned */
ev("famine").ch={who:()=>["GBR"],build:()=>({title:"Potato blight in Ireland, 1845",txt:"The potato crop has failed across Ireland. Landlords are evicting tenants who cannot pay, and grain is leaving the ports.",def:"market",opts:[{k:"market",label:"Leave it to the market",txt:"The famine lasts about five years. Hundreds of thousands die or leave. No cost to the treasury.",run(){ev("famine").run();}},{k:"relief",label:"Open the ports and fund relief",txt:"It costs six months of income, but the famine lasts about two years and many fewer die.",run(){const c=G.c.GBR;pay(c,incOf(c)*6);G.famine={p:"IRE",until:G.t+24};msg("politics","Potato blight: famine in Ireland. Relief works and open ports ease it.");}}]})};
ev("y1848").ch={who:()=>Object.keys(G.c).filter(t=>{const c=G.c[t];return c.alive&&c.civ&&c.gov==="abs"&&P(c.cap).x>1250&&P(c.cap).x<1700&&P(c.cap).y<520;}),build:pt=>({title:"1848: revolution in the capitals",txt:"Crowds fill the streets of the cities of Europe. Students, workers and liberals demand a constitution.",def:"ride",opts:[{k:"ride",label:"Ride it out",txt:"The unrest spreads: workers and the middle class become more militant for a while.",run(){ev("y1848").run();}},{k:"const",label:"Grant a constitution",txt:"We become a constitutional monarchy; unrest fades, but the old nobles are angry and we lose 3 prestige.",run(){const c=G.c[pt];c.gov="const";c.pres=Math.max(0,c.pres-3);for(const p of provsOf(pt))for(const q of p.pops)q.mil=Math.max(0,q.mil-1);msg("politics","1848: "+c.n+" grants a constitution.");}},{k:"crush",label:"Send in the troops",txt:"The revolt is crushed, but militancy rises sharply in the cities and we gain 3 prestige with the other crowns.",run(){const c=G.c[pt];ev("y1848").run();for(const p of provsOf(pt))for(const q of p.pops)if(PTYPES[q.t].s>0||q.t==="CRA")q.mil=Math.min(10,q.mil+1);c.pres+=3;}}]})};
ev("taiping").ch={who:()=>["CHI"],build:()=>({title:"The Taiping rising, 1850",txt:"A prophet who says he is Christ's younger brother has raised a huge army in the south, and the land is hungry.",def:"fight",opts:[{k:"fight",label:"Raise the banner armies",txt:"A very large rebel army takes the south. We must beat it in the field.",run(){ev("taiping").run();}},{k:"relief",label:"Cut taxes and feed the south",txt:"It costs six months of income, but the rebellion is half the size.",run(){const c=G.c.CHI;pay(c,incOf(c)*6);rebelsIn("NAN","CHI",15,3);rebelsIn("WUH","CHI",8,1);msg("war","The Taiping Heavenly Kingdom rises in the south of China; tax relief weakens it.");}},{k:"west",label:"Hire Western drill",txt:"We pay four months of income for 8 trained regiments, but the Great Powers gain a foothold: the rebellion stays large.",run(){const c=G.c.CHI;pay(c,incOf(c)*4);G.armies.push(mkArmy("CHI","NAN",{inf:8}));ev("taiping").run();}}]})};
ev("italy1").ch={who:()=>["SAR","AUS"],build:pt=>pt==="SAR"?{title:"Italy and Austria, 1859",txt:"Cavour has French promises at Plombieres. War against Austria would free Lombardy.",def:"france",opts:[{k:"france",label:"Go to war with French help",txt:"War with Austria; France joins us in most cases. Russia and Prussia stay out.",run(){ev("italy1").run();}},{k:"alone",label:"Strike alone",txt:"War with Austria without France; Russia and Prussia stay out. We gain 3 prestige for boldness if we survive.",run(){G.c.SAR.pres+=3;const w=declareWar("SAR","AUS",{k:"conquer",tag:"AUS",prov:"LOM",hist:1});if(w){w.unify="ITA";stayOut(w,["RUS","PRU"]);}}},{k:"wait",label:"Wait two more years",txt:"No war now. Relations with Austria improve slightly.",run(){evAt("italy1",24);G.c.SAR.rel.AUS=(G.c.SAR.rel.AUS||0)+10;}}]}:{title:"Piedmont threatens Lombardy, 1859",txt:"Sardinia, backed by France, will attack us unless we give way.",def:"fight",opts:[{k:"fight",label:"Fight for Lombardy",txt:"War with Sardinia-Piedmont, and probably France.",run(){ev("italy1").run();}},{k:"cede",label:"Cede Lombardy",txt:"No war. Lombardy goes to Sardinia; we lose 5 prestige.",run(){transferProv(P("LOM"),"SAR");G.unif=G.unif||{};G.unif.ITA="SAR";G.c.AUS.pres=Math.max(0,G.c.AUS.pres-5);G.c.SAR.pres+=5;}}]}};
ev("germany1").ch={who:()=>["PRU","DEN"],build:pt=>pt==="PRU"?{title:"Schleswig and Holstein, 1864",txt:"The King of Denmark has tied Schleswig to his crown. Prussia and Austria can take it.",def:"both",opts:[{k:"both",label:"Take it with Austria",txt:"War with Denmark, Austria beside us.",run(){ev("germany1").run();}},{k:"alone",label:"Take it alone",txt:"War with Denmark with no Austrian help; the gains are ours alone.",run(){declareWar("PRU","DEN",{k:"conquer",tag:"DEN",prov:"SLH",hist:1});}},{k:"drop",label:"Let it be",txt:"No war. Relations with Denmark improve; German nationalists are angry (we lose 3 prestige).",run(){G.c.PRU.pres=Math.max(0,G.c.PRU.pres-3);G.c.PRU.rel.DEN=(G.c.PRU.rel.DEN||0)+20;}}]}:{title:"Prussia and Austria march on Schleswig, 1864",txt:"Our crown is tied to Schleswig and the German states want it.",def:"fight",opts:[{k:"fight",label:"Fight on",txt:"War with Prussia, probably Austria too.",run(){ev("germany1").run();}},{k:"cede",label:"Give up Schleswig",txt:"No war. We lose Schleswig and 5 prestige.",run(){transferProv(P("SLH"),"PRU");G.c.DEN.pres=Math.max(0,G.c.DEN.pres-5);}},{k:"help",label:"Ask Britain to stand with us",txt:"War, but Britain joins us half the time.",run(){const w=ev("germany1").run();const g=G.wars[G.wars.length-1];if(g&&g.def.includes("DEN")&&alive("GBR")&&rng()<.5)pullIn(g,"GBR",2);}}]}};
ev("germany2").ch={who:()=>["PRU","AUS"],build:pt=>pt==="PRU"?{title:"Who leads Germany? 1866",txt:"Bismarck says the question of German leadership can only be settled by war with Austria.",def:"war",opts:[{k:"war",label:"War with Austria",txt:"A short, hard war for leadership of Germany. Some German states fight for Austria, and Italy joins us if it is free to. Russia, France and Britain stay out. Prussia mobilises first by rail and starts with 15 war score.",run(){ev("germany2").run();}},{k:"wait",label:"Settle quietly",txt:"No war for three years. Austria stays our ally, but German unification waits.",run(){evAt("germany2",36);}}]}:{title:"Prussia wants the leadership of Germany, 1866",txt:"Bismarck is stirring up the German question and has Italy as a friend.",def:"war",opts:[{k:"war",label:"Fight for our place in Germany",txt:"War with Prussia and Italy; Saxony, Hanover and Bavaria are each about even odds to stand with us. Russia, France and Britain stay out. Prussia mobilises first by rail and starts with 15 war score.",run(){ev("germany2").run();}},{k:"yield",label:"Accept Prussian leadership",txt:"No war. The German states go into Prussia's sphere; we lose 10 prestige and Prussia gains 6.",run(){const c=G.c.AUS;c.pres=Math.max(0,c.pres-10);G.c.PRU.pres+=6;G.unif=G.unif||{};G.unif.GER="PRU";for(const t of["HAN","SAX","BAV","WUR"])toSphere(t,"PRU");G.c.PRU.ally=G.c.PRU.ally.filter(t=>t!=="AUS");G.c.AUS.ally=G.c.AUS.ally.filter(t=>t!=="PRU");G.c.AUS.truce.PRU=G.t+60;G.c.PRU.truce.AUS=G.t+60;}}]}};
ev("germany3").ch={who:()=>["PRU","FRA"],build:pt=>pt==="PRU"?{title:"The Ems telegram, 1870",txt:"France demands that no Hohenzollern ever sit on the Spanish throne. A short edit of the king's telegram could goad Paris into war.",def:"war",opts:[{k:"war",label:"Publish the telegram",txt:"War with France. The southern German states follow us.",run(){ev("germany3").run();}},{k:"peace",label:"Soothe France",txt:"No war for two years. French relations improve; German nationalists mutter.",run(){evAt("germany3",24);G.c.PRU.rel.FRA=(G.c.PRU.rel.FRA||0)+20;}}]}:{title:"Prussia and the Spanish throne, 1870",txt:"A German prince is offered the Spanish crown. The Chamber wants war.",def:"war",opts:[{k:"war",label:"Declare war on Prussia",txt:"War with Prussia and the south German states. Our army is strong but Prussia's is better led.",run(){ev("germany3").run();}},{k:"back",label:"Accept the prince's withdrawal",txt:"No war. We lose 5 prestige and Prussia gains 5.",run(){G.c.FRA.pres=Math.max(0,G.c.FRA.pres-5);G.c.PRU.pres+=5;}}]}};
